import sys

def main():
    sys.setrecursionlimit(1 << 25)
    n = int(sys.stdin.readline())
    arr = list(map(int, sys.stdin.readline().split()))
    q = int(sys.stdin.readline())

    class SegmentTree:
        def __init__(self, data):
            self.n = len(data)
            self.size = 1
            while self.size < self.n:
                self.size <<= 1
            self.tree = [0] * (2 * self.size)

            for i in range(self.n):
                self.tree[self.size + i] = data[i]
            for i in range(self.size - 1, 0, -1):
                self.tree[i] = self.tree[2 * i] ^ self.tree[2 * i + 1]

        def update(self, pos, value):
            pos += self.size
            self.tree[pos] = value
            pos >>= 1
            while pos >= 1:
                self.tree[pos] = self.tree[2 * pos] ^ self.tree[2 * pos + 1]
                pos >>= 1

        def query(self, l, r):
            res = 0
            l += self.size
            r += self.size
            while l <= r:
                if l % 2 == 1:
                    res ^= self.tree[l]
                    l += 1
                if r % 2 == 0:
                    res ^= self.tree[r]
                    r -= 1
                l >>= 1
                r >>= 1
            return res

    seg_tree = SegmentTree(arr)

    output = []
    for _ in range(q):
        parts = sys.stdin.readline().split()
        if not parts:
            continue
        t = int(parts[0])
        if t == 1:
            x = int(parts[1])
            y = int(parts[2])
            seg_tree.update(x - 1, y)
        else:
            x = int(parts[1])
            y = int(parts[2])
            z = int(parts[3])
            xor_val = seg_tree.query(x - 1, y - 1)
            if xor_val >= z:
                output.append("happy")
            else:
                output.append("unhappy")

    print('\n'.join(output))

if __name__ == "__main__":
    main()
